for name,pairs in changes.items():
 p=r/name;s=p.read_text()
 for old,new in pairs:
  if s.count(old)!=1:raise SystemExit("Unexpected source for lead age update: "+name)
  s=s.replace(old,new,1)
 p.write_text(s)
(r/'test/lead-aging.test.mjs').write_text("import test from 'node:test';import assert from 'node:assert/strict';import {readFileSync} from 'node:fs';import vm from 'node:vm';\nimport {initialState,execute,engine} from '../server/engine.mjs';\nfunction fixture(){let state=initialState(false);for(const [id,rep,building]of [['L_aging_old','u2','hallmark'],['L_aging_recent','u2','hallmark'],['L_aging_other','u1','riverside'],['L_aging_closed','u2','hallmark']])state=execute(state,'u0',{op:'createLead',createdId:id,args:[{first:'Synthetic',last:id,rep,building,payer:'Private pay'}]});return state;}\nconst setDates=(tl,l,age,update)=>{l.created=tl.addDays(-age)+'T10:00';l.activity=update===null?[]:[{type:'note',by:l.rep,at:tl.addDays(-update)+'T11:00',text:'Synthetic staff follow-up'}];};\ntest('age and staff inactivity are independent, inclusive, exclude closed leads and ignore login/system refresh/metadata',()=>{\n const state=fixture(),tl=engine(state,'u0'),l=tl.Lead('L_aging_old');setDates(tl,l,14,3);\n for(const n of [7,13,14])assert.equal(tl.matchesLeadAging(l,{openDays:n}),true);assert.equal(tl.matchesLeadAging(l,{openDays:15}),false);\n assert.equal(tl.matchesLeadAging(l,{updateDays:3}),true);assert.equal(tl.matchesLeadAging(l,{updateDays:7}),false);\n l.updated=tl.T+'T23:59';l.activity.unshift({type:'note',by:'system',at:tl.T,text:'Automatic refresh'},{type:'note',by:'u2',auto:true,at:tl.T,text:'Automated task'},{type:'login',by:'u2',at:tl.T},{type:'email',by:'u2',at:tl.T,text:'Email (simulated)'},{type:'note',by:'missing-user',at:tl.T});assert.equal(tl.leadAging(l).noUpdateDays,3);\n l.activity.unshift({type:'note',by:'u2',at:tl.T+'T12:00',text:'Actually followed up'});assert.equal(tl.leadAging(l).noUpdateDays,0);assert.equal(tl.matchesLeadAging(l,{openDays:14}),true);assert.equal(tl.matchesLeadAging(l,{updateDays:3}),false);\n for(const stage of ['movein','lost']){l.stage=stage;assert.equal(tl.matchesLeadAging(l,{openDays:7}),false);assert.equal(tl.matchesLeadAging(l,{updateDays:3}),false);}\n});\ntest('no update since creation uses creation age; missing/invalid/future dates do not manufacture overdue claims',()=>{\n const state=fixture(),tl=engine(state,'u0'),l=tl.Lead('L_aging_old');setDates(tl,l,7,null);assert.equal(tl.leadAging(l).noUpdateDays,7);assert.equal(tl.leadAging(l).lastUpdateDay,null);\n for(const age of [3,7,14]){setDates(tl,l,age,null);assert.equal(tl.matchesLeadAging(l,{updateDays:age}),true);assert.equal(tl.matchesLeadAging(l,{updateDays:age+1}),false);}\n for(const value of [null,'invalid','2026-02-30','2099-01-01']){l.created=value;l.activity=[];assert.equal(tl.leadAging(l).openDays,null);assert.equal(tl.leadAging(l).noUpdateDays,null);assert.equal(tl.matchesLeadAging(l,{openDays:7}),false);assert.equal(tl.matchesLeadAging(l,{updateDays:3}),false);}\n l.created=tl.addDays(-14);l.activity=[{type:'note',by:'u2',at:'2099-01-01',text:'Future invalid update'}];assert.equal(tl.leadAging(l).noUpdateDays,14);\n});\ntest('filter results combine creation age, inactivity, marketer and building; hidden criteria never affect closed outcomes',()=>{\n const state=fixture(),tl=engine(state,'u0');setDates(tl,tl.Lead('L_aging_old'),14,7);setDates(tl,tl.Lead('L_aging_recent'),14,1);setDates(tl,tl.Lead('L_aging_other'),30,14);setDates(tl,tl.Lead('L_aging_closed'),30,20);tl.Lead('L_aging_closed').stage='movein';\n const UI={rep:'all',bld:'all',q:'',closed:false,openDays:'14',updateDays:'3'},ctx={UI,TL:tl};vm.createContext(ctx);const source=readFileSync(new URL('../site/app.js',import.meta.url),'utf8');vm.runInContext(source.slice(source.indexOf('function filtered(){'),source.indexOf('function marketerTag(')),ctx);const ids=()=>Array.from(ctx.filtered(),l=>l.id).sort();\n assert.deepEqual(ids(),['L_aging_old','L_aging_other']);UI.rep='u2';UI.bld='hallmark';assert.deepEqual(ids(),['L_aging_old']);UI.updateDays='all';assert.deepEqual(ids(),['L_aging_old','L_aging_recent']);UI.closed=true;UI.closedOutcome='moved';UI.openDays='999';UI.updateDays='999';assert.deepEqual(ids(),['L_aging_closed']);\n});\ntest('Pacific date conversion and midnight rollover update the age without changing stored creation dates',()=>{\n const NativeDate=Date;let clock=NativeDate.parse('2026-11-17T07:59:00Z');class TestDate extends NativeDate{constructor(...args){super(...(args.length?args:[clock]));}static now(){return clock;}}\n const state=fixture();state.me='u0';const ctx={Date:TestDate,JSON,Math,console,TL_BOOT:{state},localStorage:{getItem:()=>null,setItem:()=>{}}};ctx.window=ctx;vm.createContext(ctx);for(const f of ['data.js','libertana.js','county-roadmap.js','referral-progress.js','api.js'])vm.runInContext(readFileSync(new URL('../site/'+f,import.meta.url),'utf8'),ctx);\n const tl=ctx.TL,l=tl.Lead('L_aging_old');l.created='2026-11-03T08:00:00Z';l.activity=[{type:'note',by:'u2',at:'2026-11-14T07:30:00Z',text:'Saved note'}];assert.equal(tl.leadAging(l).openDays,13);assert.equal(tl.leadAging(l).noUpdateDays,3);clock=NativeDate.parse('2026-11-17T08:01:00Z');assert.equal(tl.leadAging(l).openDays,14);assert.equal(tl.leadAging(l).noUpdateDays,4);assert.equal(l.created,'2026-11-03T08:00:00Z');\n});\n")
